export const courseSections = sections

export const courseChapters: CourseChapter[] = drafts.map((draft) => {
  const section = sections.find((item) => item.sectionNumber === draft.section)
  if (!section) throw new Error(`Missing course section ${draft.section}`)
  return {
    ...draft,
    id: `chapter-${String(draft.chapter).padStart(2, '0')}`,
    chapterNumber: draft.chapter,
    sectionNumber: section.sectionNumber,
    sectionTitle: section.sectionTitle,
    sectionIntro: section.sectionIntro,
    domain: section.domain,
    category: section.sectionTitle,
    image: '',
    video: '',
    animation: '',
  }
})

